\label{KMtheorem}
For any two integers $u$ and $v$, let
 \begin{equation}\label{eq2.1}
F_{u, v}(Z)=Z^3-uvZ-u^2.
\end{equation}
If 
\begin{enumerate}\label{ctn3.1}
\item[(a)] $u$ and $v$ are relatively prime;
\item[(b)] $F_{u, v}(Z)$ is irreducible over $\mathbb{Q}$;
\item[(c)] the discriminant $D_{F_{u, v}}$ of $F_{u, v}(Z)$ is not a perfect square in $\mathbb{Z}$;
\item[(d)] one of the following conditions holds:
\begin{enumerate}
\item[(d.1)] $3\nmid v,$
\item[(d.2)] $3\mid v,\hspace*{3mm} uv\not\equiv 3\pmod 9, \hspace*{3mm} u\equiv v\pm 1 \pmod 9 ,$
\item[(d.3)] $3\mid v, \hspace*{3mm} uv\equiv 3 \pmod 9, \hspace*{3mm} u\equiv v\pm 1 \pmod { 27} ,$
\end{enumerate}
\end{enumerate}
then the normal closure of $\mathbb{Q}(\alpha)$, where $\alpha$ is a root of $F_{u,v}(Z)$, is a cyclic, cubic, unramified extension of  $\mathbb{K}=\mathbb{Q}(\sqrt{D_{F_{u,v}}})$; in particular, $\mathbb{K}$ has class number divisible by $3$.
Conversely, every quadratic number field $\mathbb{K}$ with class number divisible by $3$ and every unramified, cyclic and cubic extension of $\mathbb{K}$ is given by suitable choices of integers $u$ and $v$.

\label{thms} 
Assume that $S$ is a finite set such that $\{\infty\}\subset S\subset V_\mathbb{Q}$. Let $f(x)\in \mathbb{Q}[x]$ be a polynomial of degree at least $3$ with distinct roots in $\mathbb{C}$. Then the set $$\{(x, y)\in R_S\times R_S\mid y^2=f(x)\}$$
is finite, where $R_S=\{x\in \mathbb{Q}\mid v_p(x)\geq 0 \text{ for all } p\in V_\mathbb{Q}\setminus S\}$; so-called the ring of $S$-integers of $\mathbb{Q}$.

\label{abi}
The set
$$\mathcal{S} = \{k\in \mathbb{Z}^+|\text{ the class number of } \mathbb{Q}(\sqrt{40500k^3+89100k^2+65340k+16215}) \text{ is divisible by } 3\}$$
